  function carouselViewer(item){var slides=(item.slides&&item.slides.length?item.slides:[item.cover]).filter(Boolean),index=Math.min(state.selectedSlide,Math.max(0,slides.length-1)),currentName=downloadName(item,index),dots=slides.map(function(_,i){return'<button type="button" data-detail-slide="'+i+'" aria-label="Show slide '+(i+1)+'"'+(i===index?' class="isActive" aria-current="true"':'')+'></button>'}).join("");if(!slides.length)return'<div class="detailPlaceholder">📸</div>';return'<div class="carouselViewer"><div class="carouselStage"><img src="'+esc(slides[index])+'" alt="Slide '+(index+1)+' of '+slides.length+'" /><span class="carouselCounter">'+(index+1)+' / '+slides.length+'</span>'+(slides.length>1?'<button class="carouselArrow isPrevious" type="button" data-detail-step="-1" aria-label="Previous slide">←</button><button class="carouselArrow isNext" type="button" data-detail-step="1" aria-label="Next slide">→</button>':'')+'</div>'+(slides.length>1?'<div class="carouselDots" role="group" aria-label="Carousel slides">'+dots+'</div><p class="carouselHint">Use the arrows, dots, or your keyboard to review every slide.</p>':'')+'<div class="carouselDownloads"><div><strong>'+esc(currentName)+'</strong><span>Processed 1080 × 1350 publishing image</span></div><button class="button buttonGhost" type="button" data-download-current>Download slide '+(index+1)+'</button>'+(slides.length>1?'<button class="button buttonPrimary" type="button" data-download-all>Download all (.zip)</button>':'')+'</div><p class="carouselDownloadStatus" id="carouselDownloadStatus" role="status" aria-live="polite"></p></div>'}
