  function copyBlocks(item){var packages=item.copyPackages||[];if(!packages.length)return"";return'<section class="detailCopy"><header><div><p class="eyebrow">Ready to reuse</p><h3>Captions and hashtags</h3></div><span>Copied exactly as saved</span></header>'+packages.map(function(pkg,index){return'<article><div class="detailCopyHeading"><strong>'+esc(pkg.platform)+'</strong>'+(pkg.title?'<span>'+esc(pkg.title)+'</span>':'')+'</div><div class="detailCopyActions">'+(pkg.title?'<button class="button buttonGhost" type="button" data-copy-package="'+index+'" data-copy-kind="title">Copy title</button>':'')+(pkg.caption?'<button class="button buttonGhost" type="button" data-copy-package="'+index+'" data-copy-kind="caption">Copy caption</button>':'')+(pkg.hashtags?'<button class="button buttonGhost" type="button" data-copy-package="'+index+'" data-copy-kind="hashtags">Copy hashtags</button>':'')+(pkg.caption&&pkg.hashtags?'<button class="button buttonGhost" type="button" data-copy-package="'+index+'" data-copy-kind="all">Copy both</button>':'')+'</div></article>'}).join("")+'<p class="detailCopyStatus" id="detailCopyStatus" role="status" aria-live="polite"></p></section>'}
