  function detailBody(item){return'<div class="detailPreview '+(item.type==="reel"?'isReel':'isCarousel')+'">'+mediaPreview(item)+'</div><div class="detailSchedule"><article><small>Scheduled date</small><strong>'+esc(dateLabel(item.date))+'</strong></article><article><small>Eastern time</small><strong>'+esc(item.time||"Not set")+' ET</strong></article></div><div class="detailStatus"><span class="statusPill" data-status="'+item.status+'">'+esc(item.statusLabel)+'</span><span>'+esc(item.platforms.join(" · ")||"No destination recorded")+'</span></div>'+(item.description?'<p class="detailDescription">'+esc(item.description)+'</p>':'')+tagBlocks(item)+copyBlocks(item)+(collisionCount(item)?'<div class="collisionNotice">Another post is also scheduled for this date. Review the timing before publishing.</div>':'')}
