  async function rescheduleItem(key,newDate){var item=findItem(key),now=easternNow(),newTime=timeSort(item&&item.time);if(!item||item.status==="published")return;if(newDate<now.date||newDate===now.date&&newTime<=now.time){alert("Choose a future Eastern date and time.");return}if(newDate===item.date)return;var conflicts=state.items.filter(function(x){return x.id!==item.id&&x.date===newDate&&x.status!=="published"}).length,message="Move “"+item.title+"” to "+dateLabel(newDate)+" at "+(item.time||"its current time")+" ET?"+(conflicts?"\n\nThere "+(conflicts===1?"is 1 other post":"are "+conflicts+" other posts")+" scheduled that day.":"");if(!confirm(message))return;$("refreshStatus").textContent="Updating schedule…";try{if(!demo){var edits={scheduled_date:newDate,scheduled_time:newTime};await postJson(item.type==="reel"?REELS_API:CAROUSELS_API,{action:item.type==="reel"?"update_reel":"update_carousel",reel_id:item.type==="reel"?item.id:undefined,carousel_id:item.type==="carousel"?item.id:undefined,edits:edits})}item.date=newDate;if(item.raw)item.raw.scheduled_date=newDate;renderAll();$("refreshStatus").textContent="Moved to "+dateLabel(newDate)+" · "+(item.time||"current time")+" ET"}catch(error){$("refreshStatus").textContent="Schedule update failed: "+clean(error.message);alert("The schedule was not changed. "+clean(error.message))}}
